CREATE TABLE pol_grn (
  id int UNSIGNED NOT NULL,
  vo_trans_date datetime NOT NULL COMMENT 'VO Transaction Date',
  store_code varchar(20) NOT NULL COMMENT 'Store Code',
  supplier_code varchar(20) NOT NULL COMMENT 'Supplier Code',
  vo_type char(5) NOT NULL COMMENT 'VO Type',
  vo_trans_no varchar(20) NOT NULL COMMENT 'VO Transaction Number / GRN Number',
  product_code varchar(100) NOT NULL COMMENT 'Product Code',
  po_date datetime DEFAULT NULL COMMENT 'Purchase Order Date',
  po_trans_no bigint DEFAULT NULL COMMENT 'PO Transaction Number',
  vo_tot_qty int NOT NULL COMMENT 'VO Total Quantity',
  vo_net_val float NOT NULL COMMENT 'VO Net Value',
  vo_disc_val float DEFAULT NULL COMMENT 'VO Discount Value',
  vo_tax_val float DEFAULT NULL COMMENT 'VO Tax Value',
  vo_tot_val_at_price float DEFAULT NULL COMMENT 'VO Total Value At Price',
  ret_reason_code varchar(20) DEFAULT NULL COMMENT 'Return Reason Code',
  shipped_date datetime DEFAULT NULL COMMENT 'Shipped Date',
  original_cost float DEFAULT NULL COMMENT 'Original Cost',
  load_date datetime DEFAULT NULL COMMENT 'Load Date',
  vo_date datetime DEFAULT NULL COMMENT 'VO Date',
  derived_column1 varchar(255) DEFAULT NULL,
  derived_column2 varchar(255) DEFAULT NULL,
  derived_column3 varchar(255) DEFAULT NULL,
  derived_column4 varchar(255) DEFAULT NULL,
  derived_column5 varchar(255) DEFAULT NULL,
  derived_column6 varchar(255) DEFAULT NULL,
  derived_column7 varchar(255) DEFAULT NULL,
  derived_column8 varchar(255) DEFAULT NULL,
  derived_column9 varchar(255) DEFAULT NULL,
  derived_column10 varchar(255) DEFAULT NULL,
  derived_column11 varchar(255) DEFAULT NULL,
  derived_column12 varchar(255) DEFAULT NULL,
  derived_column13 varchar(255) DEFAULT NULL,
  derived_column14 varchar(255) DEFAULT NULL,
  derived_column15 varchar(255) DEFAULT NULL,
  derived_column16 varchar(255) DEFAULT NULL,
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE pol_grn
  ADD PRIMARY KEY (id),
  ADD UNIQUE KEY unique_pol_grn (vo_trans_no,product_code),
  ADD KEY idx_pol_grn_vo_trans_no (vo_trans_no),
  ADD KEY idx_pol_grn_po_trans_no (po_trans_no),
  ADD KEY idx_pol_grn_po_num_product_code (po_trans_no,product_code),
  ADD KEY idx_pol_grn_supplier_code (supplier_code),
  ADD KEY idx_pol_grn_store_code (store_code),
  ADD KEY idx_pol_grn_po_date (po_date),
  ADD KEY idx_pol_grn_vo_trans_date (vo_trans_date),
  ADD KEY idx_plg_vo_trans_date (vo_trans_date);


ALTER TABLE pol_grn
  MODIFY id int UNSIGNED NOT NULL AUTO_INCREMENT;

